Name the angle at the centre subtended by chord $MN$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[below left] {$O$};
\coordinate (M) at (-1.532,1.286);
\coordinate (N) at (1.532,1.286);
\coordinate (P) at (-0.684,-1.879);
\node[above left] at (M) {$M$};
\node[above right] at (N) {$N$};
\node[below] at (P) {$P$};
\draw (M) -- (N);
\draw (O) -- (M);
\draw (O) -- (N);
\end{tikzpicture}
[/tikz]

Name the angle at the circumference subtended by chord $RS$ at point $T$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[below left] {$O$};
\coordinate (R) at (-1.879,-0.684);
\coordinate (S) at (1.879,-0.684);
\coordinate (T) at (0.347,1.97);
\node[below left] at (R) {$R$};
\node[below right] at (S) {$S$};
\node[above] at (T) {$T$};
\draw (R) -- (S);
\draw (T) -- (R);
\draw (T) -- (S);
\end{tikzpicture}
[/tikz]

Name the chord that subtends $\angle XOY$ at the centre.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
