\coordinate (Z) at (-1.879,-0.684);
\node[above left] at (X) {$X$};
\node[right] at (Y) {$Y$};
\node[left] at (Z) {$Z$};
\draw (O) -- (X);
\draw (O) -- (Y);
\end{tikzpicture}
[/tikz]

