$C$ and $D$ lie on the same arc of the circle. Name the two angles subtended by chord $AB$ at $C$ and at $D$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[below left] {$O$};
\coordinate (A) at (-1.879,-0.684);
\coordinate (B) at (1.879,-0.684);
\coordinate (C) at (0,2);
\coordinate (D) at (1.286,1.532);
\node[below left] at (A) {$A$};
\node[below right] at (B) {$B$};
\node[above] at (C) {$C$};
\node[above right] at (D) {$D$};
\draw (A) -- (B);
\draw (C) -- (A);
\draw (C) -- (B);
\draw (D) -- (A);
\draw (D) -- (B);
\end{tikzpicture}
[/tikz]

